```zig
const std = @import("std");
const math = std.math;
const Allocator = std.mem.Allocator;

pub const Tensor = struct {
    data: []f32,
    shape: []usize,
    ndim: usize,
    allocator: Allocator,

    pub const Error = error{
        ShapeMismatch,
        MustBeSquare,
        SingularMatrix,
        OutOfMemory,
        ConvergenceFailure,
        UnsupportedDimension,
    };

    pub fn init(allocator: Allocator, shape: []const usize) !Tensor {
        const shape_copy = try allocator.dupe(usize, shape);
        errdefer allocator.free(shape_copy);
        var size: usize = 1;
        for (shape) |dim| {
            size *= dim;
        }
        const data = try allocator.alloc(f32, size);
        @memset(data, 0.0);
        return Tensor{
            .data = data,
            .shape = shape_copy,
            .ndim = shape.len,
            .allocator = allocator,
        };
    }

    pub fn deinit(self: *Tensor) void {
        self.allocator.free(self.data);
        self.allocator.free(self.shape);
    }

    pub fn copy(self: *const Tensor, allocator: Allocator) !Tensor {
        const new_tensor = try init(allocator, self.shape);
        @memcpy(new_tensor.data, self.data);
        return new_tensor;
    }

    pub fn eye(allocator: Allocator, n: usize) !Tensor {
        var t = try init(allocator, &.{ n, n });
        var i: usize = 0;
        while (i < n) : (i += 1) {
            t.data[i * n + i] = 1.0;
        }
        return t;
    }

    pub fn matmul(a: *const Tensor, b: *const Tensor, allocator: Allocator) !Tensor {
        if (a.ndim != 2 or b.ndim != 2) return Error.ShapeMismatch;
        if (a.shape[1] != b.shape[0]) return Error.ShapeMismatch;
        const m = a.shape[0];
        const p = a.shape[1];
        const n = b.shape[1];
        var res = try init(allocator, &.{ m, n });
        errdefer res.deinit();
        var i: usize = 0;
        while (i < m) : (i += 1) {
            var j: usize = 0;
            while (j < n) : (j += 1) {
                var sum: f32 = 0.0;
                var k: usize = 0;
                while (k < p) : (k += 1) {
                    sum += a.data[i * p + k] * b.data[k * n + j];
                }
                res.data[i * n + j] = sum;
            }
        }
        return res;
    }

    pub fn outer(allocator: Allocator, a: *const Tensor, b: *const Tensor) !Tensor {
        if (a.ndim == 1 and b.ndim == 1) {
            const m = a.shape[0];
            const n = b.shape[0];
            var result = try init(allocator, &.{ m, n });
            errdefer result.deinit();
            var i: usize = 0;
            while (i < m) : (i += 1) {
                var j: usize = 0;
                while (j < n) : (j += 1) {
                    result.data[i * n + j] = a.data[i] * b.data[j];
                }
            }
            return result;
        } else if (a.ndim == 2 and b.ndim == 2) {
            if (a.shape[0] != b.shape[0]) return Error.ShapeMismatch;
            const batch = a.shape[0];
            const m = a.shape[1];
            const n = b.shape[1];
            var result = try init(allocator, &.{ m, n });
            errdefer result.deinit();
            var batch_idx: usize = 0;
            while (batch_idx < batch) : (batch_idx += 1) {
                var i: usize = 0;
                while (i < m) : (i += 1) {
                    var j: usize = 0;
                    while (j < n) : (j += 1) {
                        result.data[i * n + j] += a.data[batch_idx * m + i] * b.data[batch_idx * n + j];
                    }
                }
            }
            return result;
        } else {
            return Error.UnsupportedDimension;
        }
    }

    pub fn inverse(self: *const Tensor, allocator: Allocator) !Tensor {
        if (self.ndim != 2 or self.shape[0] != self.shape[1]) return Error.MustBeSquare;
        const n = self.shape[0];
        var mat = try self.copy(allocator);
        defer mat.deinit();
        var inv = try eye(allocator, n);
        errdefer inv.deinit();
        var i: usize = 0;
        const epsilon: f32 = 1e-9;
        while (i < n) : (i += 1) {
            var pivot = i;
            var max_val = @abs(mat.data[i * n + i]);
            var j: usize = i + 1;
            while (j < n) : (j += 1) {
                const val = @abs(mat.data[j * n + i]);
                if (val > max_val) {
                    max_val = val;
                    pivot = j;
                }
            }
            if (max_val < epsilon) return Error.SingularMatrix;
            if (pivot != i) {
                var k: usize = 0;
                while (k < n) : (k += 1) {
                    const temp_mat = mat.data[i * n + k];
                    mat.data[i * n + k] = mat.data[pivot * n + k];
                    mat.data[pivot * n + k] = temp_mat;
                    const temp_inv = inv.data[i * n + k];
                    inv.data[i * n + k] = inv.data[pivot * n + k];
                    inv.data[pivot * n + k] = temp_inv;
                }
            }
            const diag = mat.data[i * n + i];
            var k: usize = 0;
            while (k < n) : (k += 1) {
                mat.data[i * n + k] /= diag;
                inv.data[i * n + k] /= diag;
            }
            j = 0;
            while (j < n) : (j += 1) {
                if (j != i) {
                    const factor = mat.data[j * n + i];
                    k = 0;
                    while (k < n) : (k += 1) {
                        mat.data[j * n + k] -= factor * mat.data[i * n + k];
                        inv.data[j * n + k] -= factor * inv.data[i * n + k];
                    }
                }
            }
        }
        return inv;
    }

    pub fn qr(self: *const Tensor, allocator: Allocator) !struct { q: Tensor, r: Tensor } {
        const m = self.shape[0];
        const n = self.shape[1];
        var q = try eye(allocator, m);
        errdefer q.deinit();
        var r = try self.copy(allocator);
        errdefer r.deinit();

        var x = try allocator.alloc(f32, m);
        defer allocator.free(x);
        var u = try allocator.alloc(f32, m);
        defer allocator.free(u);

        var j: usize = 0;
        const limit = if (m < n) m else n;
        while (j < limit) : (j += 1) {
            const vec_len = m - j;
            var i: usize = j;
            while (i < m) : (i += 1) {
                x[i - j] = r.data[i * n + j];
            }
            var norm_x: f32 = 0.0;
            var k_idx: usize = 0;
            while (k_idx < vec_len) : (k_idx += 1) {
                norm_x += x[k_idx] * x[k_idx];
            }
            norm_x = @sqrt(norm_x);
            if (norm_x < 1e-12) continue;
            const sign: f32 = if (x[0] >= 0.0) 1.0 else -1.0;
            u[0] = x[0] + sign * norm_x;
            i = 1;
            while (i < vec_len) : (i += 1) u[i] = x[i];
            var norm_u: f32 = 0.0;
            k_idx = 0;
            while (k_idx < vec_len) : (k_idx += 1) {
                norm_u += u[k_idx] * u[k_idx];
            }
            norm_u = @sqrt(norm_u);
            k_idx = 0;
            while (k_idx < vec_len) : (k_idx += 1) {
                u[k_idx] /= norm_u;
            }
            var k: usize = j;
            while (k < n) : (k += 1) {
                var dot_prod: f32 = 0.0;
                i = j;
                while (i < m) : (i += 1) {
                    dot_prod += r.data[i * n + k] * u[i - j];
                }
                dot_prod *= 2.0;
                i = j;
                while (i < m) : (i += 1) {
                    r.data[i * n + k] -= dot_prod * u[i - j];
                }
            }
            k = 0;
            while (k < m) : (k += 1) {
                var dot_prod: f32 = 0.0;
                i = j;
                while (i < m) : (i += 1) {
                    dot_prod += q.data[i * m + k] * u[i - j];
                }
                dot_prod *= 2.0;
                i = j;
                while (i < m) : (i += 1) {
                    q.data[i * m + k] -= dot_prod * u[i - j];
                }
            }
        }
        return .{ .q = q, .r = r };
    }

    pub fn eig(self: *const Tensor, allocator: Allocator) !struct { vals: Tensor, vecs: Tensor } {
        if (self.ndim != 2 or self.shape[0] != self.shape[1]) return Error.MustBeSquare;
        const n = self.shape[0];
        var mat = try self.copy(allocator);
        var vecs = try eye(allocator, n);

        errdefer {
            mat.deinit();
            vecs.deinit();
        }

        var iter: usize = 0;
        const max_iter = 1000;
        var converged_flag = false;

        while (iter < max_iter) : (iter += 1) {
            const qr_res = try mat.qr(allocator);
            const next_mat = try matmul(&qr_res.r, &qr_res.q, allocator);
            const next_vecs = try matmul(&vecs, &qr_res.q, allocator);

            mat.deinit();
            mat = next_mat;

            vecs.deinit();
            vecs = next_vecs;

            qr_res.q.deinit();
            qr_res.r.deinit();

            var sub_diag_sum: f32 = 0.0;
            var i: usize = 1;
            while (i < n) : (i += 1) {
                sub_diag_sum += @abs(mat.data[i * n + (i - 1)]);
            }
            if (sub_diag_sum < 1e-9) {
                converged_flag = true;
                break;
            }
        }

        if (!converged_flag) {
            mat.deinit();
            vecs.deinit();
            return Error.ConvergenceFailure;
        }

        var vals = try init(allocator, &.{n});
        var i: usize = 0;
        while (i < n) : (i += 1) {
            vals.data[i] = mat.data[i * n + i];
        }
        mat.deinit();

        return .{ .vals = vals, .vecs = vecs };
    }
};
