```agda
module MGTVerification where

open import Data.List using (List; []; _∷_; reverse; foldl; map)
open import Data.Char using (Char; toNat; fromNat)
open import Data.Bool using (Bool; true; false; if_then_else_)
open import Data.Nat using (ℕ; _<_; _==_; _+_)
open import Data.String using (String; toList; fromList)
open import Data.Maybe using (Maybe; nothing; just)

is-whitespace : Char → Bool
is-whitespace c = 
  let n = toNat c in
  if n == 32 then true else
  if n == 9 then true else
  if n == 10 then true else
  if n == 13 then true else false

split-helper : List Char → List Char → List (List Char) → List (List Char)
split-helper [] [] acc = reverse acc
split-helper [] current acc = reverse (reverse current ∷ acc)
split-helper (x ∷ xs) current acc with is-whitespace x
... | true = 
      if (toNat (Data.List.length current) == 0)
      then split-helper xs [] acc
      else split-helper xs [] (reverse current ∷ acc)
... | false = split-helper xs (x ∷ current) acc

mgt-tokenize : String → List String
mgt-tokenize s = 
  let chars = toList s in
  let tokens = split-helper chars [] [] in
  map fromList tokens

utf8-char-len : Char → ℕ
utf8-char-len c =
  let n = toNat c in
  if n < 128 then 1 else
  if n < 2048 then 2 else
  if n < 65536 then 3 else 4
